ledger=json.loads((P/'COMPUTE_LEDGER.json').read_text());now=datetime.datetime.now(datetime.timezone.utc);ledger['prepublication_delivery_ready_utc']=now.isoformat();ledger['elapsed_minutes_delivery_ready']=(now-datetime.datetime.fromisoformat(ledger['budget_start_utc'])).total_seconds()/60;ledger['public_CPU_replay']='PASS; no new GPU experiment after layer trace audit';assert ledger['elapsed_minutes_delivery_ready']<180
